#!/usr/bin/env python3
"""Generates wordadd.bend: Bend's Word/U32 addition is binary addition with carry."""
hdr = '''import Base
import ./natlemmas.bend as N

# GENERATED by gen_wordadd.py.

def bv(b: Bool) -> Nat:
  match b:
    case False{}:
      0n
    case True{}:
      1n

def pow2(n: Nat) -> Nat:
  match n:
    case 0n:
      1n
    case 1n+p:
      Nat.double(pow2(p))

# k * 2^n for a carry bit k.
def kt(+n: Nat, b: Bool) -> Nat:
  match b:
    case False{}:
      0n
    case True{}:
      pow2(n)

# The carry bit of a full adder (the second component of Bool.full_add).
def fk(a: Bool, +b: Bool, +c: Bool) -> Bool:
  match a:
    case False{}:
      Bool.and(b, c)
    case True{}:
      Bool.or(b, c)

# The carry out of Word.adc(n, a, b, False, c): the bit Word.add drops.
def wcarry(n: Nat, a: Word(n), b: Word(n), c: Bool) -> Bool:
  match n:
    case 0n:
      c
    case 1n+p:
      match a b:
        case WCon{ab, at} WCon{bb, bt}:
          wcarry(p, at, bt, fk(ab, bb, c))

law dk:
  for -p: Nat
  for k: Bool
  {Nat.double(kt(p, k)) == kt(1n+p, k) : Nat}

def dk(p, k):
  match k:
    case False{}:
      {==}
    case True{}:
      {==}

law assoc_r:
  for +x: Nat
  for +y: Nat
  for +z: Nat
  {Nat.add(x, Nat.add(y, z)) == Nat.add(Nat.add(x, y), z) : Nat}

def assoc_r(x, y, z):
  Equal.sym(Nat, Nat.add(Nat.add(x, y), z), Nat.add(x, Nat.add(y, z)), N.add_assoc(x, y, z))

law double_add_r:
  for +x: Nat
  for +y: Nat
  {Nat.add(Nat.double(x), Nat.double(y)) == Nat.double(Nat.add(x, y)) : Nat}

def double_add_r(x, y):
  Equal.sym(Nat, Nat.double(Nat.add(x, y)), Nat.add(Nat.double(x), Nat.double(y)), N.double_add(x, y))

# One bit position of the induction, as pure Nat algebra.
law alg:
  for +s: Nat
  for +kk: Nat
  for +ab: Nat
  for +bb: Nat
  for +cc: Nat
  for +X: Nat
  for +Y: Nat
  for +A: Nat
  for +B: Nat
  for hb: {Nat.add(Nat.add(ab, bb), cc) == Nat.add(s, Nat.double(kk)) : Nat}
  for ih: {Nat.add(Nat.add(A, B), kk) == Nat.add(X, Y) : Nat}
  {Nat.add(Nat.add(s, Nat.double(X)), Nat.double(Y)) == Nat.add(Nat.add(Nat.add(ab, Nat.double(A)), Nat.add(bb, Nat.double(B))), cc) : Nat}

def alg(s, kk, ab, bb, cc, X, Y, A, B, hb, ih):
'''
D = lambda x: f"Nat.double({x})"
add = lambda x, y: f"Nat.add({x}, {y})"
RHS = add(add(add("ab", D("A")), add("bb", D("B"))), "cc")
u, v = add("ab", "bb"), add(D("A"), D("B"))
steps = [
 ("assoc_r(s, Nat.double(X), Nat.double(Y))", "{_ == %s : Nat}" % RHS),
 ("N.double_add(X, Y)", "{Nat.add(s, _) == %s : Nat}" % RHS),
 ("ih", "{Nat.add(s, Nat.double(_)) == %s : Nat}" % RHS),
 ("double_add_r(Nat.add(A, B), kk)", "{Nat.add(s, _) == %s : Nat}" % RHS),
 ("double_add_r(A, B)", "{Nat.add(s, Nat.add(_, Nat.double(kk))) == %s : Nat}" % RHS),
 ("N.add_comm(Nat.double(kk), %s)" % v, "{Nat.add(s, _) == %s : Nat}" % RHS),
 ("N.add_assoc(s, Nat.double(kk), %s)" % v, "{_ == %s : Nat}" % RHS),
 ("hb", "{Nat.add(_, %s) == %s : Nat}" % (v, RHS)),
 ("N.swap_mid(ab, bb, Nat.double(A), Nat.double(B))", "{%s == Nat.add(_, cc) : Nat}" % add(add(u, "cc"), v)),
 ("assoc_r(%s, cc, %s)" % (u, v), "{_ == %s : Nat}" % add(add(u, v), "cc")),
 ("N.add_comm(%s, cc)" % v, "{Nat.add(%s, _) == %s : Nat}" % (u, add(add(u, v), "cc"))),
 ("assoc_r(%s, %s, cc)" % (u, v), "{%s == _ : Nat}" % add(u, add(v, "cc"))),
]
body = "".join(f"  %{e} : {p}\n" for e, p in steps) + "  {==}\n"

T, F = "True{}", "False{}"
n = lambda b: "1n" if b == T else "0n"
def leaf(ab, bb, c, ind):
    bits = [ab == T, bb == T, c == T]
    tot = sum(bits)
    s_, k = (T if tot % 2 else F), (T if tot >= 2 else F)
    X = f"Word.to_nat(p, Word.adc(p, at, bt, False{{}}, {k}))"
    Y = f"kt(p, wcarry(p, at, bt, {k}))"
    A, B = "Word.to_nat(p, at)", "Word.to_nat(p, bt)"
    lhs_nat = f"Word.to_nat(1n+p, Word.adc(1n+p, WCon{{{ab}, at}}, WCon{{{bb}, bt}}, False{{}}, {c}))"
    rhs = f"Nat.add(Nat.add(Word.to_nat(1n+p, WCon{{{ab}, at}}), Word.to_nat(1n+p, WCon{{{bb}, bt}})), bv({c}))"
    ih = f"Equal.sym(Nat, Nat.add({X}, {Y}), Nat.add(Nat.add({A}, {B}), {n(k)}), adc_ok(p, at, bt, {k}))"
    return (f"{ind}%dk(p, wcarry(p, at, bt, {k})) : {{Nat.add({lhs_nat}, _) == {rhs} : Nat}}\n"
            f"{ind}alg({n(s_)}, {n(k)}, {n(ab)}, {n(bb)}, {n(c)}, {X}, {Y}, {A}, {B}, {{==}}, {ih})")
lines = []
I = "      "
lines.append(f"{I}match a:")
lines.append(f"{I}  case WCon{{ab, at}}:")
lines.append(f"{I}    match ab:")
for ab in (F, T):
    lines.append(f"{I}      case {ab}:")
    lines.append(f"{I}        match b:")
    lines.append(f"{I}          case WCon{{bb, bt}}:")
    lines.append(f"{I}            match bb:")
    for bb in (F, T):
        lines.append(f"{I}              case {bb}:")
        lines.append(f"{I}                match c:")
        for c in (F, T):
            lines.append(f"{I}                  case {c}:")
            lines.append(leaf(ab, bb, c, I + "                    "))
cases_text = "\n".join(lines)
law = '''
# Word.add is binary addition: the sum's value plus the dropped carry times 2^n
# equals a + b + carry-in. (U32 is Word(32), so this covers every U32 `+`.)
law adc_ok:
  for +n: Nat
  for +a: Word(n)
  for +b: Word(n)
  for +c: Bool
  {Nat.add(Word.to_nat(n, Word.adc(n, a, b, False{}, c)), kt(n, wcarry(n, a, b, c))) == Nat.add(Nat.add(Word.to_nat(n, a), Word.to_nat(n, b)), bv(c)) : Nat}

def adc_ok(n, a, b, c):
  match n:
    case 0n:
      match c:
        case False{}:
          {==}
        case True{}:
          {==}
    case 1n+p:
''' + cases_text + '''

def u32carry(x: U32, y: U32) -> Bool:
  match x y:
    case U32{a} U32{b}:
      wcarry(32n, a, b, False{})

# Corollary for U32: x + y as Bend computes it, plus the dropped carry times 2^32,
# is the true sum. So a U32 `+` is exact whenever the true sum is below 2^32.
law u32_add_ok:
  for +x: U32
  for +y: U32
  {Nat.add(U32.to_nat(U32.add(x, y)), kt(32n, u32carry(x, y))) == Nat.add(U32.to_nat(x), U32.to_nat(y)) : Nat}

def u32_add_ok(x, y):
  match x y:
    case U32{a} U32{b}:
      %N.add_zero_r(Nat.add(Word.to_nat(32n, a), Word.to_nat(32n, b))) : {Nat.add(Word.to_nat(32n, Word.add(32n, a, b)), kt(32n, wcarry(32n, a, b, False{}))) == _ : Nat}
      adc_ok(32n, a, b, False{})
'''
open("wordadd.bend", "w").write(hdr + body + law)
print("wrote wordadd.bend")
